// Embeds the repo-root CHANGELOG.md verbatim into a generated TS module so the web
// client can parse it at runtime (one parser: shared/changelog/parse.ts). Run on each
// deploy and whenever CHANGELOG.md changes; the generated file is committed so local
// dev works without a build step. Usage: node tools/changelog/build.mjs
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = resolve(fileURLToPath(new URL('../../', import.meta.url)));
const source = resolve(repoRoot, 'CHANGELOG.md');
const out = resolve(repoRoot, 'web/src/changelog/source.generated.ts');

const markdown = await readFile(source, 'utf8');

// Guard against embedding a truncated or malformed CHANGELOG: require at least one dated milestone
// heading (`## [YYYY-MM-DD]`) that carries a bullet before the next heading — i.e. something
// releasedChangelog() would actually surface. This is a node-only structural check (build.mjs runs
// under plain `node`, so it can't import the TS parser); the authoritative parse stays in parse.ts. [L14]
function releasableCount(md) {
  let inDated = false, sawBullet = false, count = 0;
  for (const line of md.split(/\r?\n/)) {
    if (/^##\s+\S/.test(line)) { // a level-2 heading ("### Added" has no space after ##, so it's skipped)
      if (inDated && sawBullet) count++;
      inDated = /^##\s+\[\d{4}-\d{2}-\d{2}\]/.test(line);
      sawBullet = false;
    } else if (inDated && /^\s*[-*]\s+\S/.test(line)) {
      sawBullet = true;
    }
  }
  if (inDated && sawBullet) count++;
  return count;
}
if (releasableCount(markdown) < 1) {
  console.error('changelog: CHANGELOG.md has no dated milestone entry with bullets — refusing to emit stale/empty source.');
  process.exit(1);
}

// Non-fatal deploy reminder (this module is imported by tools/deploy/production/build-web.mjs): the
// in-game "What's new" panel and /changelog only show DATED entries, so bullets still under
// [Unreleased] won't reach players until a milestone deploy promotes them. This exact promotion was
// missed at deploy #3 (gtasf-changelog-promote-deploy4-g7nv).
function unreleasedBulletCount(md) {
  let inUnreleased = false, count = 0;
  for (const line of md.split(/\r?\n/)) {
    if (/^##\s+\S/.test(line)) { inUnreleased = /^##\s+\[unreleased\]/i.test(line); continue; }
    if (inUnreleased && /^\s*[-*]\s+\S/.test(line)) count++;
  }
  return count;
}
const pending = unreleasedBulletCount(markdown);
if (pending > 0) {
  console.warn(`changelog: ⚠ [Unreleased] has ${pending} bullet(s) not yet promoted — players' in-game "What's new" shows only DATED entries. Run \`npx tsx tools/changelog/release.mjs "<milestone>"\` before build-web at a milestone deploy (gtasf-changelog-promote-deploy4-g7nv).`);
}

// JSON.stringify yields a safe, fully escaped TS string literal regardless of content.
const body = `// GENERATED by tools/changelog/build.mjs from /CHANGELOG.md — do not edit by hand.\n`
  + `// Run \`node tools/changelog/build.mjs\` after editing CHANGELOG.md.\n`
  + `export const CHANGELOG_SOURCE = ${JSON.stringify(markdown)};\n`;

await mkdir(dirname(out), { recursive: true });
await writeFile(out, body);
console.log(`changelog: embedded ${markdown.length} bytes from CHANGELOG.md into ${out.replace(repoRoot + '/', '')}`);
